steps.script:
for c in tree.root.get_children():
	if c is Window and c != tree.root:
		c.hide()
		c.queue_free()
return true

var cc = tree.current_scene.get_node_or_null("CommandController")
if cc == null:
	return "NO_CONTROLLER"
cc._refresh_ui()
return true

var alive = 0
for m in GameState.state["units"]["U_BOYZ_B"]["models"]:
	if m.get("alive", true):
		alive += 1
return alive + int(GameState.state["units"]["U_BOYZ_B"]["flags"]["ork11e_breakin_heads"]["d3"])
